import {scenarios,themes,buildSlides,deckText,validateMaterial,validateDeck} from './presentation-model.mjs';
import {keys,list,write,projects,preferences,recordTask} from './state.mjs';
import {esc,icon,download,formatDate} from './ui.mjs';
let deck,ctx,root,busy=false,dirty=false,selected=0,tab='upload',preview=0,controller;
const $=s=>root?.querySelector(s),defaultDeck=()=>({title:'',scenario:scenarios[0],projectId:'',degree:preferences().degree||'本科',minutes:10,pages:12,language:'中文',theme:'academic',author:'',school:'',advisor:'',material:'',fileName:'',slides:[]});
export const presentationHasWork=()=>!!root?.querySelector('.ppt-grid')&&(dirty||busy);
export function presentationRouteGuard(){if(!root?.querySelector('.ppt-grid'))return true;if(busy){ctx.notify('正在处理，请稍候。');return false;}if(dirty&&!window.confirm('有未保存的演示修改。离开会丢失这些修改，确定离开？'))return false;dirty=false;return true;}
window.addEventListener('beforeunload',e=>{if(presentationHasWork()){e.preventDefault();e.returnValue='';}});
export function mountPresentation(context,draftId,projectId){controller?.abort();controller=new AbortController();ctx=context;const d=list(keys.drafts).find(d=>String(d.id)===String(draftId)&&d.tool==='ppt');deck=d?.presentation?structuredClone(d.presentation):defaultDeck();if(d){deck.id=d.id;deck.projectId=d.projectId||'';if(!d.presentation){deck.title=d.title;deck.material=d.text||'';deck.fileName='旧版演示提纲';}}else deck.projectId=projectId||'';dirty=false;busy=false;selected=0;preview=0;tab=deck.material?'paste':'upload';root=document.querySelector('.dashboard');draw();root.addEventListener('click',actions,{signal:controller.signal});root.addEventListener('input',inputChange,{signal:controller.signal});root.addEventListener('change',inputChange,{signal:controller.signal});}
function selectOptions(values,value){return values.map(v=>`<option ${String(v)===String(value)?'selected':''}>${esc(v)}</option>`).join('');}
function field(id,label,value,max=100){return `<label>${label}<input data-field="${id}" aria-label="${label}" maxlength="${max}" value="${esc(value)}"></label>`;}
function slidePreview(slide,small=false){const t=themes[deck.theme]||themes.academic;return `<div class="ppt-slide ${slide.layout==='cover'?'cover':''} ${small?'mini':''}" style="--ppt-accent:#${t.accent};--ppt-dark:#${t.dark}"><span>PaperKnow · ${esc(deck.scenario)}</span><h3>${esc(slide.title)}</h3><p>${esc(slide.body)}</p><small>${small?'':'16:9 · 文本预览'}</small></div>`;}
function draw(){const slides=deck.slides,show=slides.length?slides[Math.min(preview,slides.length-1)]:{title:'论文题目示例',body:'毕业论文答辩\n作者 / 院校 / 导师',layout:'cover'};root.innerHTML=`<div class="hub-heading"><div><h1>PPT 创作</h1><p>从论文到汇报，让研究表达更清晰。</p></div><a class="btn secondary" href="#assets">${icon('folder',16)} 我的演示文稿</a></div><div class="ppt-grid"><section class="card ppt-card"><h2>创建演示文稿 <span class="hub-badge">本地创作</span></h2><div class="ppt-tabs" role="group" aria-label="汇报场景">${scenarios.map(s=>`<button data-scenario="${s}" aria-pressed="${deck.scenario===s}" class="${deck.scenario===s?'active':''}">${s}</button>`).join('')}</div><ol class="ppt-steps">${['导入材料','确认大纲','编辑演示','导出文件'].map((s,i)=>`<li class="${i===(slides.length?2:0)?'active':''}"><span>${i+1}</span>${s}</li>`).join('')}</ol><b class="ppt-label">选择论文来源</b><div class="ppt-source-tabs">${[['upload','upload','上传论文'],['existing','folder','选择已有成果'],['paste','file','粘贴 / 核对材料']].map(([id,ico,n])=>`<button data-source="${id}" aria-pressed="${id===tab}" class="${id===tab?'active':''}">${icon(ico,16)}${n}</button>`).join('')}</div>${tab==='upload'?`<label class="ppt-drop" id="ppt-drop">${icon('upload',38)}<b>${busy?'正在解析…':'上传论文或报告'}</b><span>DOCX / PDF / TXT · 最大 50MB · PDF 最多 150 页</span><small>文本型 PDF；暂不支持扫描件 OCR。</small><input type="file" id="ppt-file" accept=".docx,.pdf,.txt" aria-label="上传论文或报告" ${busy?'disabled':''}></label>`:tab==='paste'?`<label class="ppt-label">材料正文<textarea data-field="material" aria-label="材料正文" maxlength="80000" rows="7" placeholder="粘贴需要整理的研究材料；不会自动上传。">${esc(deck.material)}</textarea></label>`:'<div class="ppt-drop"><b>从论文成果开始</b><button class="btn secondary" data-action="choose">选择已有成果</button><small>复制正文，原成果不变。</small></div>'}<p id="ppt-material-state" class="hub-footnote">${deck.material?`${esc(deck.fileName||'粘贴材料')} · ${deck.material.length.toLocaleString('zh-CN')} 字符`:'尚未导入材料'}</p><div class="ppt-fields"><label>所属项目<select data-field="projectId" aria-label="所属项目"><option value="">未归入项目</option>${projects().map(p=>`<option value="${esc(p.id)}" ${p.id===deck.projectId?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label>${field('title','演示标题',deck.title,120)}</div><div class="ppt-fields four"><label>学段<select data-field="degree" aria-label="学段">${selectOptions(['专科','本科','硕士','博士','科研人员'],deck.degree)}</select></label><label>汇报时长（分钟）<input type="number" data-field="minutes" aria-label="汇报时长" min="1" max="120" value="${deck.minutes}"></label><label>目标页数<input type="number" data-field="pages" aria-label="目标页数" min="6" max="30" value="${deck.pages}"></label><label>演示语言<select data-field="language" aria-label="演示语言">${selectOptions(['中文','英文'],deck.language)}</select></label></div><details class="ppt-more"><summary>更多设置（作者、学校、导师）</summary><div class="ppt-fields">${field('author','作者',deck.author)}${field('school','学校 / 单位',deck.school)}${field('advisor','导师',deck.advisor)}</div></details><div class="ppt-actions"><button class="btn secondary" data-action="save">保存草稿</button><button class="btn primary" data-action="generate" ${busy?'disabled':''}>${slides.length?'重新创建大纲':'创建演示大纲'} ${icon('arrow',16)}</button></div><p class="hub-footnote">本地结构模板，未调用 AI；不会自动提炼或翻译材料。研究数据、结论与引用需依据实际材料填写。</p><p id="ppt-status" role="status" class="hub-footnote">${dirty?'有未保存修改':'当前浏览器保存，请及时导出备份。'}</p></section><aside><section class="card ppt-card"><h2>模板与效果预览 <span class="hub-badge gray">${slides.length?'当前文稿':'模板示例'}</span></h2><div class="ppt-tabs" role="group" aria-label="演示模板">${Object.entries(themes).map(([id,t])=>`<button data-theme="${id}" aria-pressed="${deck.theme===id}" class="${deck.theme===id?'active':''}">${t.name}</button>`).join('')}</div><div id="ppt-live-preview">${slidePreview(show)}</div><div class="ppt-thumbnails">${(slides.length?slides.slice(0,3):[{title:'论文题目示例',body:'答辩封面',layout:'cover'},{title:'研究方法',body:'填写实际研究设计'},{title:'结果分析',body:'填写真实研究证据'}]).map((s,i)=>`<button data-preview="${i}" aria-label="预览第 ${i+1} 页">${slidePreview(s,true)}</button>`).join('')}</div><p class="hub-footnote">16:9 · 文本可编辑 · 预览不保证与 PowerPoint 字体换行完全一致。</p></section><section class="card ppt-card"><h2>${slides.length?'演示大纲':'大纲结构预览'}</h2><div class="ppt-outline">${(slides.length?slides:[{title:'研究背景与问题'},{title:'文献回顾'},{title:'研究设计与方法'},{title:'研究结果与分析'},{title:'结论与研究贡献'},{title:'致谢与答辩'}]).map((s,i)=>`<button data-edit="${i}" ${slides.length?'':'disabled'}><span>${String(i+1).padStart(2,'0')}</span>${esc(s.title)}${slides.length?icon('pen',14):''}</button>`).join('')}</div><p class="hub-footnote">${slides.length?'点击页面继续编辑；空缺内容不会被自动补造。':'示例结构，创建后可调整。'}</p></section></aside></div>${slides.length?editor():''}<section class="card ppt-card"><div class="hub-card-heading"><h2>最近演示文稿</h2><a href="#assets">查看全部 →</a></div><div class="ppt-recents">${list(keys.drafts).filter(d=>d.tool==='ppt').sort((a,b)=>String(b.updatedAt).localeCompare(String(a.updatedAt))).slice(0,3).map(d=>`<a href="#draft/${esc(d.id)}">${icon('chart',24)}<div><b>${esc(d.title)}</b><p>${d.presentation?.slides?.length||0} 页 · ${formatDate(d.updatedAt)}${d.presentation?'':' · 旧版提纲'}</p><span>继续编辑 →</span></div></a>`).join('')||'<p class="hub-footnote">尚无保存的演示文稿，导入材料后开始创建。</p>'}</div></section><div class="ppt-backup">${icon('shield',20)}<div><b>本地解析与编辑，不自动上传论文</b><p>可导出编辑文本、可编辑 PPTX 和打印预览；云端同步与 AI 生成尚未接入。</p></div></div>`;bindDrop();}
function editor(){const s=deck.slides[selected]||deck.slides[0];selected=deck.slides.indexOf(s);return `<section class="card ppt-card" id="ppt-editor"><div class="hub-card-heading"><h2>逐页编辑 <span class="hub-badge">第 ${selected+1} / ${deck.slides.length} 页</span></h2><div class="ppt-actions"><button class="btn secondary" data-action="add">添加页</button><button class="btn secondary" data-action="up" ${selected===0?'disabled':''}>上移</button><button class="btn secondary" data-action="down" ${selected===deck.slides.length-1?'disabled':''}>下移</button><button class="btn secondary" data-action="remove" ${deck.slides.length===1?'disabled':''}>移除页</button></div></div><div class="ppt-editor-grid"><div><label class="ppt-label">页面标题<input data-slide="title" aria-label="页面标题" maxlength="120" value="${esc(s.title)}"></label><label class="ppt-label">页面正文<textarea data-slide="body" aria-label="页面正文" maxlength="1400" rows="6">${esc(s.body)}</textarea></label><label class="ppt-label">演讲备注<textarea data-slide="notes" aria-label="演讲备注" maxlength="3000" rows="3">${esc(s.notes)}</textarea></label></div><div><details open><summary>参考材料（仅供核对）</summary><textarea readonly aria-label="参考材料" rows="10">${esc(deck.material)}</textarea></details><p class="hub-footnote">选取实际材料复制到左侧正文；每页建议保留 3–5 个要点。长文本在 PPTX 中可能缩小字号，请导出后核对。</p></div></div><div class="ppt-actions"><button class="btn primary" data-action="export">导出可编辑 PPTX</button><button class="btn secondary" data-action="print">打印预览 / 保存 PDF</button><button class="btn secondary" data-action="text">导出文本</button><button class="btn secondary" data-action="json">导出文稿备份</button><button class="btn secondary" data-action="save">保存文稿</button></div></section>`;}
function mark(){dirty=true;const status=$('#ppt-status');if(status)status.textContent='有未保存修改，请保存草稿或导出备份。';}
function inputChange(e){if(e.target.dataset.field){deck[e.target.dataset.field]=['pages','minutes'].includes(e.target.dataset.field)?Number(e.target.value):e.target.value;mark();if(e.target.dataset.field==='material')$('#ppt-material-state').textContent=`${deck.fileName||'粘贴材料'} · ${deck.material.length.toLocaleString('zh-CN')} 字符`;}if(e.target.dataset.slide){deck.slides[selected][e.target.dataset.slide]=e.target.value;mark();preview=selected;if($('#ppt-live-preview'))$('#ppt-live-preview').innerHTML=slidePreview(deck.slides[selected]);const entry=$(`[data-edit="${selected}"]`);if(entry)entry.innerHTML=`<span>${String(selected+1).padStart(2,'0')}</span>${esc(deck.slides[selected].title)}${icon('pen',14)}`;}if(e.target.id==='ppt-file')readFile(e.target.files[0]);}
function freeze(value){root?.querySelectorAll('input,textarea,select,button').forEach(el=>{if(value){el.dataset.pptDisabled=String(el.disabled);el.disabled=true;}else if(el.dataset.pptDisabled!==undefined){el.disabled=el.dataset.pptDisabled==='true';delete el.dataset.pptDisabled;}});}
function bindDrop(){const drop=$('#ppt-drop');if(!drop)return;drop.addEventListener('dragover',e=>{e.preventDefault();drop.classList.add('drag');});drop.addEventListener('dragleave',()=>drop.classList.remove('drag'));drop.addEventListener('drop',e=>{e.preventDefault();drop.classList.remove('drag');if(e.dataTransfer.files.length!==1)return ctx.notify('每次请选择一份文件。');readFile(e.dataTransfer.files[0]);});}
async function readFile(file){if(!file||busy)return;if(!/\.(docx|pdf|txt)$/i.test(file.name)||file.size>50*1024*1024)return ctx.notify('请选择 50MB 以内的 DOCX、PDF 或 TXT。');if(deck.material&&!confirm('替换当前参考材料？已编辑的页面会保留，请重新核对。'))return;busy=true;freeze(true);const mounted=root;$('#ppt-material-state').textContent='正在本地解析…';try{const {extractFile}=await import('/precheck/assets/parsers.js');const r=await extractFile(file);const text=validateMaterial(r.text);if(!mounted.isConnected)return;deck.material=text;deck.fileName=file.name;if(!deck.title)deck.title=file.name.replace(/\.[^.]+$/,'');mark();tab='paste';ctx.notify(r.warnings.length?'文件已解析，部分页面有解析提示，请核对正文。':'已解析正文，请核对。');}catch(e){ctx.notify(e.message||'文件解析失败。');}finally{busy=false;if(mounted.isConnected)draw();}}
function save(){if(!deck.title.trim())return ctx.notify('请填写演示标题。');try{const rows=list(keys.drafts),old=rows.find(d=>d.id===deck.id),now=new Date().toISOString(),id=deck.id||crypto.randomUUID();const saved={...old,id,title:deck.title.trim(),tool:'ppt',kind:deck.slides.length?'演示文稿':'演示草稿',stage:deck.slides.length?'presentation':'draft',projectId:deck.projectId,createdAt:old?.createdAt||now,updatedAt:now,text:deckText(deck),presentation:structuredClone({...deck,id})};write(keys.drafts,old?rows.map(d=>d.id===id?saved:d):[saved,...rows]);deck.id=id;dirty=false;try{recordTask({id:'draft-'+id,title:deck.title,kind:'本地演示保存',status:'completed',projectId:deck.projectId,url:'#draft/'+id});}catch{}ctx.notify('文稿已保存到当前浏览器。');draw();}catch{ctx.notify('浏览器保存失败，请导出文稿备份。');}}
function choose(){const rows=list(keys.drafts).filter(d=>d.tool!=='ppt'&&(d.text?.trim()||d.html));ctx.modal('选择已有成果',`<p class="hub-footnote">复制已有正文；大纲与模板不代表真实论文。</p>${rows.map(d=>`<button class="ppt-existing" data-ppt-existing="${esc(d.id)}"><b>${esc(d.title)}</b><small>${esc(d.kind||'创作成果')}</small></button>`).join('')||'<p>暂无可导入成果。</p>'}`);document.querySelectorAll('[data-ppt-existing]').forEach(b=>b.addEventListener('click',()=>{const d=rows.find(d=>String(d.id)===b.dataset.pptExisting);if(deck.material&&!confirm('替换当前参考材料？'))return;let text=d.text||'';if(!text&&d.html){const div=document.createElement('div');div.innerHTML=d.html;div.querySelectorAll('p,h3,h4').forEach(n=>n.append(document.createTextNode('\n')));text=div.textContent||'';}try{deck.material=validateMaterial(text);deck.title=d.title;deck.projectId=d.projectId||deck.projectId;deck.fileName='已有成果：'+d.title;tab='paste';mark();document.querySelector('#workspace-dialog').close();draw();}catch(e){ctx.notify(e.message);}}));}
async function actions(e){const b=e.target.closest('button');if(!b)return;if(busy)return ctx.notify('正在处理，请稍候。');if(b.dataset.scenario){deck.scenario=b.dataset.scenario;mark();draw();return;}if(b.dataset.theme){deck.theme=b.dataset.theme;mark();draw();return;}if(b.dataset.source){tab=b.dataset.source;draw();if(tab==='existing')choose();return;}if(b.dataset.preview!==undefined){preview=Number(b.dataset.preview);draw();return;}if(b.dataset.edit!==undefined){selected=Number(b.dataset.edit);preview=selected;draw();$('#ppt-editor')?.scrollIntoView({block:'start',behavior:'smooth'});return;}try{switch(b.dataset.action){case 'choose':choose();break;case 'generate':if(deck.slides.length&&!confirm('重新创建大纲将替换当前全部页面，请先保存或导出备份。确定继续？'))return;deck.slides=buildSlides(deck);selected=0;preview=0;mark();draw();ctx.notify('已创建结构大纲，请逐页补充真实材料。');break;case 'save':save();break;case 'add':if(deck.slides.length>=30)throw new Error('最多 30 页。');deck.slides.splice(selected+1,0,{id:crypto.randomUUID(),title:'新页面',body:'',notes:'',layout:'content'});selected++;preview=selected;mark();draw();break;case 'remove':if(!confirm('移除当前页？此操作不会修改已保存的文稿。'))return;deck.slides.splice(selected,1);selected=Math.max(0,selected-1);preview=selected;mark();draw();break;case 'up':case 'down':{const next=selected+(b.dataset.action==='up'?-1:1);if(next<0||next>=deck.slides.length)return;[deck.slides[selected],deck.slides[next]]=[deck.slides[next],deck.slides[selected]];selected=next;preview=selected;mark();draw();break;}case 'export':busy=true;freeze(true);try{const {exportPresentation}=await import('./assets/presentation-export.js');await exportPresentation(deck);ctx.notify('已导出 PPTX，请在 PowerPoint 中核对排版。');}finally{busy=false;freeze(false);}break;case 'text':download(deck.title+'.txt',deckText(deck));break;case 'json':download((deck.title||'演示草稿')+'-PaperKnow.json',JSON.stringify(deck,null,2),'application/json');break;case 'print':validateDeck(deck);download(deck.title+'-打印预览.html',printHtml(),'text/html');ctx.notify('已下载打印预览，打开后选择打印并保存 PDF。');break;}}catch(error){ctx.notify(error.message||'操作失败，请重试。');}}
function printHtml(){return `<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>${esc(deck.title)}</title><style>body{font-family:Arial,'Microsoft YaHei',sans-serif;margin:0;background:#eee}button{margin:20px;padding:12px}section{box-sizing:border-box;background:#fff;width:297mm;height:167mm;padding:22mm;page-break-after:always;border-left:4mm solid #${themes[deck.theme].accent}}h1{font-size:30pt;color:#${themes[deck.theme].dark}}p{font-size:20pt;white-space:pre-wrap;overflow-wrap:anywhere}@page{size:297mm 167mm;margin:0}@media print{button{display:none}body{background:white}}</style><button onclick="window.print()">打印 / 保存 PDF</button>${deck.slides.map(s=>`<section><small>PaperKnow · ${esc(deck.scenario)}</small><h1>${esc(s.title)}</h1><p>${esc(s.body)}</p></section>`).join('')}</html>`;}
